import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger.js';
import Lenis from 'lenis';

gsap.registerPlugin(ScrollTrigger);

document.addEventListener('DOMContentLoaded', () => {
	console.log('⚡ In-Situ Engineering Portfolio Initialized.');

	// Smooth Scroll with Lenis
	const lenis = new Lenis({
		duration: 1.2,
		easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
		direction: 'vertical',
		gestureDirection: 'vertical',
		smooth: true,
		mouseMultiplier: 1,
		smoothTouch: false,
		touchMultiplier: 2,
		infinite: false,
	});

	function raf(time) {
		lenis.raf(time);
		requestAnimationFrame(raf);
	}
	requestAnimationFrame(raf);

	lenis.on('scroll', ScrollTrigger.update);
	gsap.ticker.add((time) => {
		lenis.raf(time * 1000);
	});

	// Custom Cursor Follower
	const cursorDot = document.querySelector('.cursor-dot');
	const cursorRing = document.querySelector('.cursor-ring');

	if (cursorDot && cursorRing) {
		window.addEventListener('mousemove', (e) => {
			const posX = e.clientX;
			const posY = e.clientY;

			cursorDot.style.left = `${posX}px`;
			cursorDot.style.top = `${posY}px`;

			cursorRing.animate({
				left: `${posX}px`,
				top: `${posY}px`
			}, { duration: 300, fill: 'forwards' });
		});

		const interactiveElements = document.querySelectorAll('a, button, .project-cover, .tech-card, .timeline__card, .stat-box');
		interactiveElements.forEach((el) => {
			el.addEventListener('mouseenter', () => document.body.classList.add('cursor-hover'));
			el.addEventListener('mouseleave', () => document.body.classList.remove('cursor-hover'));
		});
	}

	// Preloader Progress Counter & Exit Wipe
	const preloader = document.getElementById('preloader');
	const preloaderBar = document.getElementById('preloader-bar');
	const preloaderCounter = document.getElementById('preloader-counter');

	if (preloader && preloaderBar && preloaderCounter) {
		let count = 0;
		const interval = setInterval(() => {
			count += Math.floor(Math.random() * 15) + 5;
			if (count >= 100) {
				count = 100;
				clearInterval(interval);
				preloaderBar.style.width = '100%';
				preloaderCounter.textContent = '100%';

				setTimeout(() => {
					preloader.classList.add('preloader--loaded');
				}, 400);
			} else {
				preloaderBar.style.width = `${count}%`;
				preloaderCounter.textContent = `${count}%`;
			}
		}, 60);
	}

	// Hero Canvas Animated Gradient Blobs
	const canvas = document.getElementById('hero-canvas');
	if (canvas) {
		const ctx = canvas.getContext('2d');
		let width = (canvas.width = window.innerWidth);
		let height = (canvas.height = window.innerHeight);

		window.addEventListener('resize', () => {
			width = canvas.width = window.innerWidth;
			height = canvas.height = window.innerHeight;
		});

		const blobs = [
			{ x: width * 0.2, y: height * 0.3, r: 350, vx: 0.5, vy: 0.3, color: 'rgba(0, 242, 254, 0.05)' },
			{ x: width * 0.8, y: height * 0.7, r: 400, vx: -0.4, vy: -0.5, color: 'rgba(92, 62, 232, 0.04)' },
			{ x: width * 0.5, y: height * 0.5, r: 300, vx: 0.3, vy: -0.4, color: 'rgba(0, 230, 153, 0.04)' }
		];

		function animateCanvas() {
			ctx.clearRect(0, 0, width, height);

			blobs.forEach((b) => {
				b.x += b.vx;
				b.y += b.vy;

				if (b.x < -100 || b.x > width + 100) b.vx *= -1;
				if (b.y < -100 || b.y > height + 100) b.vy *= -1;

				const gradient = ctx.createRadialGradient(b.x, b.y, 0, b.x, b.y, b.r);
				gradient.addColorStop(0, b.color);
				gradient.addColorStop(1, 'transparent');

				ctx.fillStyle = gradient;
				ctx.beginPath();
				ctx.arc(b.x, b.y, b.r, 0, Math.PI * 2);
				ctx.fill();
			});

			requestAnimationFrame(animateCanvas);
		}
		animateCanvas();
	}

	// In-Situ Hero Code Execution Terminal
	const runBtn = document.getElementById('run-insitu-btn');
	const terminal = document.getElementById('insitu-terminal-output');
	if (runBtn && terminal) {
		runBtn.addEventListener('click', () => {
			terminal.classList.toggle('hidden');
		});
	}

	// In-Situ 3D Mesh Wireframe Canvas Simulation
	const meshCanvas = document.getElementById('insitu-mesh-canvas');
	const toggleMeshBtn = document.getElementById('toggle-mesh-btn');
	if (meshCanvas) {
		const mctx = meshCanvas.getContext('2d');
		let isWireframe = true;
		let angle = 0;

		if (toggleMeshBtn) {
			toggleMeshBtn.addEventListener('click', (e) => {
				e.preventDefault();
				isWireframe = !isWireframe;
				toggleMeshBtn.innerHTML = isWireframe 
					? '<i class="fa-solid fa-cube"></i> Toggle Wireframe Mesh' 
					: '<i class="fa-solid fa-circle-nodes"></i> Toggle Point Cloud';
			});
		}

		function drawMesh() {
			const w = meshCanvas.width;
			const h = meshCanvas.height;
			mctx.clearRect(0, 0, w, h);

			const cx = w / 2;
			const cy = h / 2;
			const radius = 45;
			const nodes = 18;

			mctx.strokeStyle = 'rgba(0, 242, 254, 0.6)';
			mctx.fillStyle = 'rgba(0, 230, 153, 0.8)';
			mctx.lineWidth = 1;

			const points = [];
			for (let i = 0; i < nodes; i++) {
				const theta = (i / nodes) * Math.PI * 2 + angle;
				const phi = Math.sin(angle * 2 + i) * 0.4;
				const px = cx + Math.cos(theta) * radius * Math.cos(phi);
				const py = cy + Math.sin(theta) * radius * 0.8;
				points.push({ x: px, y: py });
			}

			if (isWireframe) {
				mctx.beginPath();
				for (let i = 0; i < points.length; i++) {
					const next = points[(i + 1) % points.length];
					mctx.moveTo(points[i].x, points[i].y);
					mctx.lineTo(next.x, next.y);
					mctx.lineTo(cx, cy);
				}
				mctx.stroke();
			} else {
				points.forEach((p) => {
					mctx.beginPath();
					mctx.arc(p.x, p.y, 3, 0, Math.PI * 2);
					mctx.fill();
				});
			}

			angle += 0.02;
			requestAnimationFrame(drawMesh);
		}
		drawMesh();
	}

	// In-Situ Live NLP Sentiment Vectorizer
	const nlpInput = document.getElementById('nlp-input');
	const posScore = document.getElementById('pos-score');
	const neuScore = document.getElementById('neu-score');
	const negScore = document.getElementById('neg-score');

	if (nlpInput && posScore && neuScore && negScore) {
		nlpInput.addEventListener('input', (e) => {
			const val = e.target.value.toLowerCase();
			let pos = 0.5;
			let neu = 0.3;
			let neg = 0.2;

			if (val.includes('incredible') || val.includes('good') || val.includes('fast') || val.includes('great') || val.includes('love')) {
				pos = 0.94; neu = 0.05; neg = 0.01;
			} else if (val.includes('slow') || val.includes('bad') || val.includes('error') || val.includes('fail')) {
				pos = 0.05; neu = 0.15; neg = 0.80;
			} else {
				pos = 0.45; neu = 0.45; neg = 0.10;
			}

			posScore.textContent = pos.toFixed(2);
			neuScore.textContent = neu.toFixed(2);
			negScore.textContent = neg.toFixed(2);
		});
	}

	// GSAP Infinite Horizontal Project Carousel
	const projectSlider = document.querySelector('.project-slider');
	const projectCards = document.querySelectorAll('.project-card-item');

	if (projectSlider && projectCards.length > 0) {
		const cardWidth = 540;
		const gap = 24;
		const totalWidth = (cardWidth + gap) * projectCards.length;

		projectCards.forEach((card, index) => {
			gsap.set(card, { x: index * (cardWidth + gap) });
		});

		let curX = 0;
		let targetX = 0;

		window.addEventListener('wheel', (e) => {
			if (window.scrollY >= projectSlider.offsetTop - 300 && window.scrollY <= projectSlider.offsetTop + 600) {
				targetX -= e.deltaY * 0.8;
			}
		});

		let isDragging = false;
		let startX = 0;
		let dragStartTargetX = 0;

		projectSlider.addEventListener('mousedown', (e) => {
			isDragging = true;
			startX = e.clientX;
			dragStartTargetX = targetX;
		});

		window.addEventListener('mousemove', (e) => {
			if (!isDragging) return;
			const delta = e.clientX - startX;
			targetX = dragStartTargetX + delta * 1.5;
		});

		window.addEventListener('mouseup', () => {
			isDragging = false;
		});

		function animateCarousel() {
			curX += (targetX - curX) * 0.1;

			projectCards.forEach((card, i) => {
				let xPos = (i * (cardWidth + gap) + curX) % totalWidth;
				if (xPos < -(cardWidth + gap)) {
					xPos += totalWidth;
				}
				gsap.set(card, { x: xPos });
			});

			requestAnimationFrame(animateCarousel);
		}
		animateCarousel();
	}

	// Scroll Reveal Animations
	const revealElements = document.querySelectorAll('.anim-reveal');
	const observer = new IntersectionObserver((entries) => {
		entries.forEach((entry) => {
			if (entry.isIntersecting) {
				entry.target.classList.add('is-visible');
			}
		});
	}, { threshold: 0.15 });

	revealElements.forEach((el) => observer.observe(el));
});